from flask import Flask, jsonify, request, render_template_string
import os
import re

app = Flask(__name__)

# LEXGUARD server-side plagiarism analysis engine.
KEYWORDS = {
    "int","long","short","float","double","char","void","bool","boolean","string",
    "const","let","var","auto","static","public","private","protected","class","struct",
    "function","def","return","if","else","elif","for","while","do","switch","case",
    "break","continue","in","of","new","this","self","true","false","null","None",
    "True","False","try","catch","except","throw","raise","import","from","package"
}

MULTI_OPS = {
    "===","!==",">>>","<<=",">>=","==","!=","<=",">=","&&","||","++","--",
    "+=","-=","*=","/=","%=","=>","->","::","<<",">>"
}

def tokenize(source: str, norm_id: bool, norm_lit: bool, strip_comments: bool):
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        ch = source[i]
        nxt = source[i + 1] if i + 1 < n else ""

        if ch.isspace():
            i += 1
            continue

        if (ch == "/" and nxt == "/") or ch == "#":
            start = i
            while i < n and source[i] != "\n":
                i += 1
            if not strip_comments:
                tokens.append({"type": "DELIM", "norm": "COMMENT",
                                "raw": source[start:i], "start": start, "end": i})
            continue

        if ch == "/" and nxt == "*":
            start = i
            i += 2
            while i < n and not (source[i] == "*" and i + 1 < n and source[i+1] == "/"):
                i += 1
            if i < n:
                i += 2
            if not strip_comments:
                tokens.append({"type": "DELIM", "norm": "COMMENT",
                                "raw": source[start:i], "start": start, "end": i})
            continue

        if ch in "\"'`":
            quote = ch
            start = i
            i += 1
            while i < n:
                if source[i] == "\\":
                    i += 2
                    continue
                if source[i] == quote:
                    i += 1
                    break
                i += 1
            raw = source[start:i]
            tokens.append({"type": "LIT", "norm": "STR" if norm_lit else raw,
                           "raw": raw, "start": start, "end": i})
            continue

        if ch.isdigit():
            start = i
            while i < n and re.match(r"[0-9a-fA-FxX._]", source[i]):
                i += 1
            raw = source[start:i]
            tokens.append({"type": "LIT", "norm": "NUM" if norm_lit else raw,
                           "raw": raw, "start": start, "end": i})
            continue

        if re.match(r"[A-Za-z_$]", ch):
            start = i
            i += 1
            while i < n and re.match(r"[A-Za-z0-9_$]", source[i]):
                i += 1
            raw = source[start:i]
            if raw in KEYWORDS:
                tokens.append({"type": "KW", "norm": raw.upper(),
                               "raw": raw, "start": start, "end": i})
            else:
                tokens.append({"type": "ID", "norm": "ID" if norm_id else raw,
                               "raw": raw, "start": start, "end": i})
            continue

        three = ch + nxt + (source[i+2] if i + 2 < n else "")
        two = ch + nxt
        if three in MULTI_OPS:
            tokens.append({"type": "OP", "norm": three, "raw": three,
                           "start": i, "end": i+3})
            i += 3
            continue
        if two in MULTI_OPS:
            tokens.append({"type": "OP", "norm": two, "raw": two,
                           "start": i, "end": i+2})
            i += 2
            continue

        if ch in "+-*/%=<>!&|^~?:":
            typ = "OP"
        else:
            typ = "DELIM"
        tokens.append({"type": typ, "norm": ch, "raw": ch,
                       "start": i, "end": i+1})
        i += 1

    return tokens

def fnv1a(text: str) -> int:
    h = 0x811C9DC5
    for byte in text.encode("utf-8"):
        h ^= byte
        h = (h * 0x01000193) & 0xFFFFFFFF
    return h

def build_kgrams(tokens, k):
    if not tokens:
        return []
    k = min(k, len(tokens))
    result = []
    for i in range(len(tokens) - k + 1):
        window = tokens[i:i+k]
        signature = "|".join(f"{t['type']}:{t['norm']}" for t in window)
        result.append({
            "index": i,
            "startToken": i,
            "endToken": i + k - 1,
            "label": " ".join(t["norm"] for t in window),
            "hash": fnv1a(signature),
            "winnowed": False,
            "shared": False,
        })
    return result

def winnow(shingles, w):
    if not shingles:
        return set()
    w = min(w, len(shingles))
    fingerprints = set()
    min_idx = -1

    for i in range(len(shingles) - w + 1):
        if min_idx < i:
            min_idx = i
            for j in range(i + 1, i + w):
                if shingles[j]["hash"] <= shingles[min_idx]["hash"]:
                    min_idx = j
        else:
            right = i + w - 1
            if shingles[right]["hash"] <= shingles[min_idx]["hash"]:
                min_idx = right

        shingles[min_idx]["winnowed"] = True
        fingerprints.add(shingles[min_idx]["hash"])

    return fingerprints

def analyze(payload):
    code_a = str(payload.get("codeA", ""))
    code_b = str(payload.get("codeB", ""))
    k = max(2, min(8, int(payload.get("k", 4))))
    w = max(2, min(6, int(payload.get("w", 4))))
    norm_id = bool(payload.get("normId", True))
    norm_lit = bool(payload.get("normLit", True))
    strip_comments = bool(payload.get("stripComments", True))

    tokens_a = tokenize(code_a, norm_id, norm_lit, strip_comments)
    tokens_b = tokenize(code_b, norm_id, norm_lit, strip_comments)

    shingles_a = build_kgrams(tokens_a, k)
    shingles_b = build_kgrams(tokens_b, k)

    fp_a = winnow(shingles_a, w)
    fp_b = winnow(shingles_b, w)

    shared = fp_a & fp_b
    union = fp_a | fp_b

    jaccard = (len(shared) / len(union) * 100) if union else 0.0
    min_size = min(len(fp_a), len(fp_b))
    containment = (len(shared) / min_size * 100) if min_size else 0.0

    # Mark shared fingerprints and tokens for visual inspection.
    for sh in shingles_a:
        sh["shared"] = sh["hash"] in shared
    for sh in shingles_b:
        sh["shared"] = sh["hash"] in shared

    token_hashes_a = [[] for _ in tokens_a]
    for sh in shingles_a:
        for idx in range(sh["startToken"], sh["endToken"] + 1):
            token_hashes_a[idx].append(sh["hash"])

    token_hashes_b = [[] for _ in tokens_b]
    for sh in shingles_b:
        for idx in range(sh["startToken"], sh["endToken"] + 1):
            token_hashes_b[idx].append(sh["hash"])

    for idx, tok in enumerate(tokens_a):
        tok["shared_hashes"] = [h for h in token_hashes_a[idx] if h in shared]
    for idx, tok in enumerate(tokens_b):
        tok["shared_hashes"] = [h for h in token_hashes_b[idx] if h in shared]

    return {
        "tokensA": tokens_a,
        "tokensB": tokens_b,
        "shinglesA": shingles_a,
        "shinglesB": shingles_b,
        "fpA": sorted(fp_a),
        "fpB": sorted(fp_b),
        "sharedCount": len(shared),
        "unionCount": len(union),
        "jaccard": jaccard,
        "containment": containment,
        "uniqueKgramsA": len({s["hash"] for s in shingles_a}),
        "uniqueKgramsB": len({s["hash"] for s in shingles_b}),
    }

@app.get("/")
def index():
    return render_template_string(PAGE)

@app.post("/api/scan")
def scan():
    try:
        return jsonify(analyze(request.get_json(silent=True) or {}))
    except Exception as exc:
        return jsonify({"error": f"Scan failed: {exc}"}), 400

@app.get("/health")
def health():
    return jsonify({"status": "ok"})

